head.script:
scwin.tData = {
    "description" : "[multiselect > E > onviewchange]<br/>MultiSelect 컴포넌트에서 사용자의 조작에 의해 아이템 선택이 변경되면 발생합니다.",
    "validation" : [
        "MultiSelect 컴포넌트에서 사용자의 조작에 의해 아이템 선택이 변경되면 발생합니다.",
        "이벤트 핸들러로 변경된 아이템 정보 객체 info 가 전달됩니다. info 는 oldValue, newValue, oldSelectedIndex, newSelectedIndex 속성을 포함합니다.",
        "변경전에 선택된 아이템이 없거나 아이템을 2 개 이상 선택하지 않은 경우 info.oldValue 와 info.oldSelectedIndex 는 ''(Empty String) 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onviewchange =====");
    wf_body_bottom.getObj("scwin").setReturnValue("typeof info: " + typeof info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue: [" + (info ? info.oldValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue: [" + (info ? info.newValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldSelectedIndex: [" + (info ? info.oldSelectedIndex : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newSelectedIndex: [" + (info ? info.newSelectedIndex : "") + "]");
};



scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onviewchange"]);

    await $c.gcm.createBasicMultiSelect('', eList);
}
